            .bind(now)
            .bind(now)
            .execute(&self.pool)
            .await
            .unwrap();
        }

        async fn revoke_role(&self, calendar_id: i64, user_id: i64) {
            sqlx::query("DELETE FROM calendar_acl WHERE calendar_id = ? AND user_id = ?")
                .bind(calendar_id)
                .bind(user_id)
                .execute(&self.pool)
                .await
                .unwrap();
        }
    }

