    let repository = CaldavRepository::new(pool.clone());
    let resource = repository
        .ensure_resource(calendar_id, event_id, 1000)
        .await
        .unwrap();

    // Duplicate (calendar_id, uid) must fail.
    assert!(
        insert_resource(
            &pool,
            other_event_id,
            calendar_id,
            &resource.uid,
            "other-name"
        )
        .await
        .is_err()
    );
    // Duplicate (calendar_id, resource_name) must fail.
    assert!(
        insert_resource(
            &pool,
            other_event_id,
            calendar_id,
