        Some(("intruder@example.test", &intruder_password)),
    )
    .await;
    assert_eq!(status, StatusCode::NOT_FOUND);
    assert!(body.is_empty());
}

#[tokio::test]
async fn unauthenticated_get_is_401() {
    let (
        _temp_dir,
