                 RETURNING id",
            )
            .bind(owner_user_id)
            .bind(name)
            .bind(color)
            .bind(archived as i32)
            .bind(now)
            .bind(now)
            .fetch_one(&self.pool)
            .await
            .unwrap();
            sqlx::query(
                "INSERT INTO calendar_acl (calendar_id, user_id, role, created_at, updated_at)
                 VALUES (?, ?, 'owner', ?, ?)",
            )
            .bind(id)
            .bind(owner_user_id)
            .bind(now)
            .bind(now)
            .execute(&self.pool)
            .await
            .unwrap();
            id
        }

        async fn grant_role(&self, calendar_id: i64, user_id: i64, role: &str) {
            let now = 1000i64;
            sqlx::query(
                "INSERT INTO calendar_acl (calendar_id, user_id, role, created_at, updated_at)
                 VALUES (?, ?, ?, ?, ?)",
            )
            .bind(calendar_id)
            .bind(user_id)
            .bind(role)
            .bind(now)
            .bind(now)
            .execute(&self.pool)
            .await
            .unwrap();
        }

        async fn revoke_role(&self, calendar_id: i64, user_id: i64) {
            sqlx::query("DELETE FROM calendar_acl WHERE calendar_id = ? AND user_id = ?")
                .bind(calendar_id)
                .bind(user_id)
                .execute(&self.pool)
                .await
                .unwrap();
        }
    }

