        .ensure_resource(calendar_id, event_id, 1000)
        .await
        .unwrap();

    // Duplicate (calendar_id, uid) must fail.
    assert!(
        insert_resource(
            &pool,
            other_event_id,
            calendar_id,
            &resource.uid,
            "other-name"
        )
        .await
        .is_err()
    );
    // Duplicate (calendar_id, resource_name) must fail.
    assert!(
        insert_resource(
            &pool,
            other_event_id,
            calendar_id,
            "other-uid",
            &resource.resource_name
        )
        .await
        .is_err()
    );
    // The same uid in a different calendar is allowed.
    let other_calendar_id = create_calendar(&pool, user_id).await;
    insert_resource(
        &pool,
        other_event_id,
        other_calendar_id,
        &resource.uid,
        "other-name",
